import{_ as e,o as r,c as a,a3 as o}from"./chunks/framework.BM_-pWjS.js";const i="/bridge-lite/manual/assets/filter.BYl2TNdw.png",b=JSON.parse('{"title":"Filters","description":"","frontmatter":{},"headers":[],"relativePath":"en/filter-spec.md","filePath":"en/filter-spec.md"}'),d={name:"en/filter-spec.md"};function l(s,t,h,n,p,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h1><p>The filters in the left sidebar let you narrow down the photos displayed in the grid. The toggle at the top of the panel also enables <a href="./flat.html">flat view</a>, which disables grouping entirely.</p><p><img src="'+i+'" alt="Filter panel"></p><h2 id="file-type" tabindex="-1">FILE TYPE <a class="header-anchor" href="#file-type" aria-label="Permalink to &quot;FILE TYPE&quot;">​</a></h2><p>A concept unique to bridge-lite, which is built around grouping. This filter controls which file type becomes the <strong>representative photo</strong> of each group.</p><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>SOOC</td><td>In-camera JPEG (Straight Out Of Camera)</td></tr><tr><td>RAW</td><td>RAW file</td></tr><tr><td>Developed</td><td>JPEG / TIFF exported from Lightroom or similar</td></tr><tr><td>Indeterminate</td><td>Files that cannot be classified into any of the above</td></tr></tbody></table><p>Only checked types are shown as group representatives. When multiple types are checked, the priority order <strong>Developed &gt; SOOC &gt; RAW</strong> determines which type appears.</p><p><strong>Camera only</strong> hides photos that have no EXIF data (e.g. screenshots).</p><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><p>Say you have 10 photos — 5 that look great straight out of camera, and 5 you want to develop. After importing the developed files into the folder, checking both <strong>SOOC</strong> and <strong>Developed</strong> lets you view all 10 photos at once: the developed version for those 5, and the SOOC for the rest.</p><h2 id="metadata-filters-checkboxes" tabindex="-1">Metadata filters (checkboxes) <a class="header-anchor" href="#metadata-filters-checkboxes" aria-label="Permalink to &quot;Metadata filters (checkboxes)&quot;">​</a></h2><p>Filter by EXIF metadata attached to your photos.</p><table tabindex="0"><thead><tr><th>Filter</th><th>Description</th></tr></thead><tbody><tr><td>Camera</td><td>Filter by camera model</td></tr><tr><td>Photographer</td><td>Filter by photographer</td></tr><tr><td>Lens</td><td>Filter by lens</td></tr><tr><td>Rating</td><td>Filter by star rating</td></tr><tr><td>Label</td><td>Filter by label</td></tr></tbody></table><h2 id="metadata-filters-histograms" tabindex="-1">Metadata filters (histograms) <a class="header-anchor" href="#metadata-filters-histograms" aria-label="Permalink to &quot;Metadata filters (histograms)&quot;">​</a></h2><p>Filter by numeric ranges derived from EXIF metadata. Each filter displays a histogram of the distribution — useful not only for filtering but also for understanding your own shooting tendencies (e.g. which focal lengths you use most).</p><table tabindex="0"><thead><tr><th>Filter</th><th>Description</th></tr></thead><tbody><tr><td>ISO</td><td>Filter by ISO value</td></tr><tr><td>Focal length</td><td>Filter by focal length</td></tr><tr><td>Shutter speed</td><td>Filter by shutter speed</td></tr><tr><td>Aperture</td><td>Filter by aperture (f-number)</td></tr><tr><td>Date &amp; time</td><td>Filter by shooting date and time</td></tr><tr><td>Saturation</td><td>Filter by saturation</td></tr></tbody></table><h2 id="other-operations" tabindex="-1">Other operations <a class="header-anchor" href="#other-operations" aria-label="Permalink to &quot;Other operations&quot;">​</a></h2><h3 id="collapsing-filters" tabindex="-1">Collapsing filters <a class="header-anchor" href="#collapsing-filters" aria-label="Permalink to &quot;Collapsing filters&quot;">​</a></h3><p>Click the arrow on the right side of any filter header to collapse or expand it. Folding away filters you don&#39;t need keeps the sidebar tidy.</p><h3 id="reordering-filters" tabindex="-1">Reordering filters <a class="header-anchor" href="#reordering-filters" aria-label="Permalink to &quot;Reordering filters&quot;">​</a></h3><p>You can change the order of filters in the Settings screen. Moving your most-used filters to the top makes them easier to reach.</p>',21)])])}const g=e(d,[["render",l]]);export{b as __pageData,g as default};
